import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "./Navbar.css";
import { Link, useLocation } from "react-router-dom";

function Navbar() {
  const location = useLocation();
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);

  const navItems = [
    { path: "/", label: "Configurar Test" },
    { path: "/tutorial", label: "Tutorial" },
  ];

  const isActive = (itemPath) => {
    if (itemPath === "/") return location.pathname === "/";
    return location.pathname.startsWith(itemPath);
  };

  const toggleUserMenu = () => setIsUserMenuOpen(!isUserMenuOpen);
  const closeUserMenu = () => setIsUserMenuOpen(false);

  return (
    <nav className="navbar navbar-expand-lg navbar-dark app-navbar shadow-sm">
      <div className="container">
        <Link to="/" className="navbar-brand d-flex align-items-center">
          <img
            src="/iconSP.png"
            alt="Logo"
            width="34"
            height="34"
            className="d-inline-block align-top me-2"
          />
          <span className="app-navbar-brand-text">Performance System</span>
        </Link>

        <button
          className="navbar-toggler"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#navbarNav"
          aria-controls="navbarNav"
          aria-expanded="false"
          aria-label="Toggle navigation"
          onClick={closeUserMenu}
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div
          className="collapse navbar-collapse justify-content-between"
          id="navbarNav"
        >
          {/* Menú central */}
          <ul className="navbar-nav mx-auto align-items-center gap-2">
            {navItems.map((item) => (
              <li
                key={item.path}
                className={`nav-item ${
                  isActive(item.path) ? "app-nav-item-active" : ""
                }`}
              >
                <Link to={item.path} className="nav-link app-nav-link">
                  {item.label}
                </Link>
              </li>
            ))}
          </ul>

          {/* Usuario */}
          <div className="d-flex align-items-center ms-auto app-user-menu-wrapper">
            <div className="dropdown">
              <button
                className="btn btn-outline-light app-user-menu-toggle d-flex align-items-center"
                type="button"
                onClick={toggleUserMenu}
              >
                <div className="app-user-avatar d-flex align-items-center justify-content-center me-2">
                  AD
                </div>

                <div className="app-user-info d-none d-md-flex flex-column text-start me-2">
                  <span className="app-user-name">Admin User</span>
                  <span className="app-user-email">admin@inf.udec.cl</span>
                </div>

                <span
                  className={`app-user-menu-icon ${
                    isUserMenuOpen ? "rotate" : ""
                  }`}
                >
                  ▾
                </span>
              </button>

              <div
                className={`dropdown-menu dropdown-menu-end app-user-dropdown-menu ${
                  isUserMenuOpen ? "show" : ""
                }`}
              >
                <h6 className="dropdown-header">Sesión actual</h6>

                <span className="dropdown-item-text">
                  <strong>Admin User</strong>
                  <br />
                  admin@inf.udec.cl
                </span>

                <div className="dropdown-divider"></div>

                <Link
                  to="/admin/users"
                  className="dropdown-item"
                  onClick={closeUserMenu}
                >
                  Panel de administración
                </Link>

                <button className="dropdown-item" type="button">
                  Mi perfil 
                </button>

                <div className="dropdown-divider"></div>

                <Link
                  to="/login"
                  className="dropdown-item text-danger"
                  onClick={closeUserMenu}
                >
                  Cerrar sesión
                </Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;
