import React, { useMemo, useState } from "react";
import { useNavigate, useParams, Link } from "react-router-dom";
import "./AdminUser.css";
import mockUsers from "../common/mockUsers";

const AdminUserDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const user =
    mockUsers.find((u) => String(u.id) === String(id)) || mockUsers[0];

  const [statusFilter, setStatusFilter] = useState("all");
  const [problemFilter, setProblemFilter] = useState("");

  const allExecutions = useMemo(
    () =>
      [
        {
          id: "LCS-001",
          problem: "LCS clásico",
          status: "Aprobado",
          date: "2025-11-10 15:39",
          durationMs: 183,
          energy: "Baja",
        },
        {
          id: "CAMM-103",
          problem: "CAMM benchmark 1",
          status: "Rechazado",
          date: "2025-11-08 12:05",
          durationMs: 941,
          energy: "Media",
        },
        {
          id: "LCS-045",
          problem: "LCS input grande",
          status: "Error",
          date: "2025-11-06 20:10",
          durationMs: 0,
          energy: "-",
        },
        {
          id: "CAMM-201",
          problem: "CAMM dataset 2",
          status: "Aprobado",
          date: "2025-11-01 09:31",
          durationMs: 512,
          energy: "Media",
        },
        {
          id: "LCS-078",
          problem: "LCS caso promedio",
          status: "Aprobado",
          date: "2025-10-28 18:47",
          durationMs: 290,
          energy: "Baja",
        },
        {
          id: "CAMM-300",
          problem: "CAMM stress test",
          status: "Rechazado",
          date: "2025-10-20 11:05",
          durationMs: 1200,
          energy: "Alta",
        },
      ].map((e) => ({ ...e, userId: user.id })),
    [user.id]
  );

  const filteredExecutions = useMemo(() => {
    let data = [...allExecutions];

    if (statusFilter !== "all") {
      data = data.filter((e) => e.status === statusFilter);
    }

    if (problemFilter.trim() !== "") {
      const q = problemFilter.toLowerCase();
      data = data.filter((e) => e.problem.toLowerCase().includes(q));
    }
    return data;
  }, [allExecutions, statusFilter, problemFilter]);

  const totalExecs = allExecutions.length;
  const approved = allExecutions.filter((e) => e.status === "Aprobado").length;
  const rejected = allExecutions.filter((e) => e.status === "Rechazado").length;
  const errors = allExecutions.filter((e) => e.status === "Error").length;

  const renderExecutionStatusClass = (status) => {
    if (status === "Aprobado") return "app-status-badge--success";
    if (status === "Rechazado") return "app-status-badge--warning";
    if (status === "Error") return "app-status-badge--error";
    return "";
  };

  const renderUserStatusClass = (status) => {
    if (status === "Activo") return "app-status-badge--success";
    if (status === "Bloqueado") return "app-status-badge--error";
    return "app-status-badge--warning";
  };

  return (
    <div className="app-page admin-page container-fluid py-4">
      <div className="row justify-content-center">
        <div className="col-12 col-xxl-10">
          {/* Header */}
          <div className="d-flex flex-wrap justify-content-between align-items-start mb-3 gap-2">
            <div>
              <button
                type="button"
                className="btn btn-link p-0 mb-2 small text-decoration-none"
                onClick={() => navigate(-1)}
              >
                ← Volver a administración de usuarios
              </button>
              <h2 className="app-title mb-1">Detalle de usuario</h2>
              <p className="text-muted mb-0">
                Información resumida y ejecuciones asociadas al usuario.
              </p>
            </div>

            <div className="text-end">
              <span
                className={`app-status-badge ${renderUserStatusClass(
                  user.status
                )} mb-1`}
              >
                {user.status}
              </span>
              <div className="small text-muted">
                Última actividad: {user.lastActivity}
              </div>
            </div>
          </div>

          <div className="row g-3">
            {/* Panel info usuario */}
            <div className="col-lg-4">
              <div className="card app-card admin-card h-100">
                <div className="card-body">
                  <h5 className="card-title mb-3">Perfil</h5>

                  <div className="user-detail-avatar mb-3">
                    <span>{user.name.charAt(0)}</span>
                  </div>

                  <h4 className="mb-1">{user.name}</h4>
                  <p className="text-muted mb-3 small">{user.email}</p>

                  <div className="mb-3">
                    <span className="badge rounded-pill bg-light text-dark me-2">
                      {user.role}
                    </span>
                    <span className="badge rounded-pill bg-primary-subtle text-primary-emphasis">
                      ID: {user.id}
                    </span>
                  </div>

                  <dl className="row small mb-0">
                    <dt className="col-5 text-muted">Creado</dt>
                    <dd className="col-7 mb-1">{user.createdAt}</dd>

                    <dt className="col-5 text-muted">Últ. ejecución</dt>
                    <dd className="col-7 mb-1">{user.lastExecutionAt}</dd>

                    <dt className="col-5 text-muted">Submissions</dt>
                    <dd className="col-7 mb-1">
                      {user.submissionsCount} ( {user.passedCount} ok /{" "}
                      {user.failedCount} err )
                    </dd>

                    <dt className="col-5 text-muted">Estado actual</dt>
                    <dd className="col-7 mb-1">{user.lastExecutionStatus}</dd>
                  </dl>

                  <hr className="my-3" />

                  <div className="d-grid gap-2">
                    <button
                      type="button"
                      className="btn btn-outline-secondary btn-sm"
                    >
                      Ver perfil completo (mock)
                    </button>
                    <button
                      type="button"
                      className="btn btn-outline-danger btn-sm"
                    >
                      Bloquear usuario (mock)
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* Panel ejecuciones */}
            <div className="col-lg-8">
              <div className="card app-card admin-card h-100 d-flex flex-column">
                <div className="card-body d-flex flex-column">
                  <div className="d-flex flex-wrap justify-content-between align-items-center mb-3 gap-2">
                    <div>
                      <h5 className="card-title mb-1">Ejecuciones recientes</h5>
                      <p className="text-muted small mb-0">
                        Resumen de ejecuciones LCS / CAMM asociadas al usuario.
                      </p>
                    </div>

                    <div className="d-flex flex-wrap gap-2 text-end">
                      <div className="badge-summary badge-summary-compact">
                        <span className="summary-label">Total</span>
                        <span className="summary-value">{totalExecs}</span>
                      </div>
                      <div className="badge-summary badge-summary-compact badge-summary-success">
                        <span className="summary-label">Aprobadas</span>
                        <span className="summary-value">{approved}</span>
                      </div>
                      <div className="badge-summary badge-summary-compact badge-summary-warning">
                        <span className="summary-label">Rechazadas</span>
                        <span className="summary-value">{rejected}</span>
                      </div>
                      <div className="badge-summary badge-summary-compact badge-summary-error">
                        <span className="summary-label">Errores</span>
                        <span className="summary-value">{errors}</span>
                      </div>
                    </div>
                  </div>

                  {/* Filtros ejecuciones */}
                  <div className="row g-2 align-items-end mb-3">
                    <div className="col-12 col-md-6">
                      <label className="form-label app-label-sm mb-1">
                        Filtrar por nombre de problema
                      </label>
                      <input
                        type="text"
                        className="form-control form-control-sm"
                        placeholder="Ej: LCS, CAMM..."
                        value={problemFilter}
                        onChange={(e) => setProblemFilter(e.target.value)}
                      />
                    </div>
                    <div className="col-6 col-md-3">
                      <label className="form-label app-label-sm mb-1">
                        Estado
                      </label>
                      <select
                        className="form-select form-select-sm"
                        value={statusFilter}
                        onChange={(e) => setStatusFilter(e.target.value)}
                      >
                        <option value="all">Todos</option>
                        <option value="Aprobado">Aprobado</option>
                        <option value="Rechazado">Rechazado</option>
                        <option value="Error">Error</option>
                      </select>
                    </div>
                    <div className="col-6 col-md-3 text-md-end">
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => {
                          setStatusFilter("all");
                          setProblemFilter("");
                        }}
                      >
                        Limpiar filtros
                      </button>
                    </div>
                  </div>

                  {/* Tabla ejecuciones */}
                  <div className="table-responsive app-table-wrapper admin-table-wrapper flex-grow-1">
                    <table className="table table-hover align-middle app-table admin-table mb-0">
                      <thead>
                        <tr>
                          <th>ID</th>
                          <th>Problema</th>
                          <th className="text-center">Estado</th>
                          <th className="text-center">Duración (ms)</th>
                          <th className="text-center">Energía</th>
                          <th className="text-end">Acciones</th>
                        </tr>
                      </thead>
                      <tbody>
                        {filteredExecutions.map((e) => (
                          <tr key={e.id}>
                            <td className="small text-muted">{e.id}</td>
                            <td>
                              <div className="d-flex flex-column">
                                <span className="fw-semibold">{e.problem}</span>
                                <span className="text-muted small">
                                  {e.date}
                                </span>
                              </div>
                            </td>
                            <td className="text-center">
                              <span
                                className={`app-status-badge ${renderExecutionStatusClass(
                                  e.status
                                )}`}
                              >
                                {e.status}
                              </span>
                            </td>
                            <td className="text-center">{e.durationMs}</td>
                            <td className="text-center">{e.energy}</td>
                            <td className="text-end">
                              <div className="btn-group btn-group-sm">
                                <button
                                  type="button"
                                  className="btn btn-outline-secondary btn-sm"
                                >
                                  Resumen
                                </button>
                                <button
                                  type="button"
                                  className="btn btn-outline-secondary btn-sm"
                                >
                                  Re-ejecutar
                                </button>
                                <button
                                  type="button"
                                  className="btn btn-outline-secondary btn-sm"
                                >
                                  Ver detalle
                                </button>
                              </div>
                            </td>
                          </tr>
                        ))}

                        {filteredExecutions.length === 0 && (
                          <tr>
                            <td colSpan="6" className="text-center py-4">
                              <span className="text-muted small">
                                No hay ejecuciones que coincidan con los filtros
                                actuales.
                              </span>
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>

                  <div className="admin-table-footer text-muted small px-2 pt-2">
                    Mostrando {filteredExecutions.length} de {totalExecs}{" "}
                    ejecuciones.
                  </div>

                  {/* Acciones inferiores */}
                  <div className="mt-3 d-flex justify-content-between align-items-center">
                    <span className="small text-muted">
                    </span>
                    <Link
                      to="/admin/users"
                      className="btn btn-outline-secondary btn-sm"
                    >
                      Volver al listado de usuarios
                    </Link>
                  </div>
                </div>
              </div>
            </div>
            {/* fin col */}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminUserDetail;
