import React, { Component } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";

import RenderForm from "./screens/RenderForm";
import RenderImage from "./screens/RenderImage";
import Navbar from "./common/Navbar";
import TaskPage from "./screens/TaskPage";
import RenderDoubleForm from "./screens/RenderDobuleForm";
import TutorialPage from "./screens/TutorialPage";
import Login from "./screens/Login";

// Administración de usuarios
import AdminUser from "./screens/AdminUser";
import AdminUserDetail from "./screens/AdminUserDetail";


class App extends Component {
  state = {
    tasksState: {
      lcs: false,
      camm: false,
    },
  };

  handleTaskToggle = (taskId, value) => {
    this.setState((prevState) => ({
      tasksState: {
        ...prevState.tasksState,
        [taskId]: value,
      },
    }));
  };

  componentDidMount() {
    document.title = "Performance System";
  }

  render() {
    const { tasksState } = this.state;

    return (
      <div>
        <BrowserRouter>
          {/* Ocultamos el Navbar en la ruta /login */}
          {window.location.pathname !== "/login" && (
            <Navbar tasksState={tasksState} />
          )}

          <Routes>
            {/* Login */}
            <Route path="/login" element={<Login />} />

            {/* Página de tareas */}
            <Route
              path="/taskpage"
              element={
                <TaskPage
                  onTaskToggle={this.handleTaskToggle}
                  tasksState={tasksState}
                />
              }
            />

            {/* Inicio */}
            <Route path="/" element={<RenderForm />} />

            {/* Comparación de ejecuciones */}
            <Route
              path="/compare"
              element={<RenderDoubleForm tasksState={tasksState} />}
            />

            {/* Mostrar imagen/código por nombre */}
            <Route path="/code/:codename" element={<RenderImage />} />

            {/* Tutorial y ejemplos */}
            <Route path="/tutorial" element={<TutorialPage />} />

            {/* Administración de usuarios */}
            <Route path="/admin/users" element={<AdminUser />} />
            <Route path="/admin/users/:id" element={<AdminUserDetail />} />
          </Routes>
        </BrowserRouter>
      </div>
    );
  }
}

export default App;
