import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Login.css";

const Login = () => {
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const validate = () => {
    const newErrors = {};

    if (!email.trim()) {
      newErrors.email = "El correo es obligatorio.";
    } else if (!email.endsWith("@inf.udec.cl")) {
      newErrors.email = "Debe usar un correo institucional @inf.udec.cl.";
    }

    if (!password.trim()) {
      newErrors.password = "La contraseña es obligatoria.";
    } else if (password.length < 6) {
      newErrors.password = "La contraseña debe tener al menos 6 caracteres.";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const simulateLoginSuccess = (mode) => {
    // Aquí luego puedes guardar el token real (localStorage, context, etc.)
    console.log(`Login simulado vía ${mode}`, { email });

    // Por ahora, simplemente redirigimos a la vista principal (inicio)
    navigate("/");
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validate()) return;

    setIsSubmitting(true);

    // Más adelante reemplazas esto con un POST real a tu backend
    setTimeout(() => {
      simulateLoginSuccess("form");
      setIsSubmitting(false);
    }, 800);
  };

  const handleGoogleLogin = () => {
    setIsSubmitting(true);

    // Aquí luego iría la redirección a Google OAuth
    setTimeout(() => {
      simulateLoginSuccess("google");
      setIsSubmitting(false);
    }, 800);
  };

  return (
    <div className="login-page">
      <div className="login-overlay" />

      <div className="login-layout">
        {/* Panel de marca / explicación */}
        <section className="login-side">
          <div className="login-brand">
            <img
              src="/iconSP.png"
              alt="Logo Performance System"
              className="login-logo"
            />
            <h1 className="login-brand-title">Performance System</h1>
            <p className="login-brand-subtitle">
              Plataforma para medir y analizar el rendimiento de código C++
              usando métricas de hardware reales.
            </p>
          </div>

          <ul className="login-highlights">
            <li>
              Análisis de rendimiento para <strong>LCS, CAMM y SIZE</strong>.
            </li>
            <li>
              Métricas avanzadas: <strong>IPC, caché, energía, ciclos</strong>.
            </li>
            <li>
              Integración con cuentas institucionales
              <strong> @inf.udec.cl</strong>.
            </li>
          </ul>

          <p className="login-note">
            Esta pantalla es un mockup visual. Más adelante se conectará a
            autenticación real (OAuth Google + backend).
          </p>
        </section>

        {/* Panel de login */}
        <section className="login-card">
          <header className="login-header">
            <h2 className="login-title">Acceso institucional</h2>
            <p className="login-subtitle">
              Inicia sesión con tu correo de la carrera para continuar.
            </p>
          </header>

          <div className="login-oauth">
            <button
              type="button"
              className="login-google-btn"
              onClick={handleGoogleLogin}
              disabled={isSubmitting}
            >
              <span className="login-google-icon">G</span>
              <span>
                {isSubmitting
                  ? "Conectando con Google..."
                  : "Continuar con Google"}
              </span>
            </button>
            <p className="login-oauth-hint">
              Se utilizará tu cuenta institucional para generar un token seguro
              y acceder al sistema. 
            </p>
          </div>

          <div className="login-divider">
            <span className="login-divider-line" />
            <span className="login-divider-label">o usa correo y contraseña</span>
            <span className="login-divider-line" />
          </div>

          <form onSubmit={handleSubmit} className="login-form" noValidate>
            <div className="login-field">
              <label htmlFor="email" className="login-label">
                Correo institucional
              </label>
              <input
                id="email"
                type="email"
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className={`login-input ${
                  errors.email ? "login-input--error" : ""
                }`}
                placeholder="nombre.apellido@inf.udec.cl"
              />
              {errors.email && (
                <span className="login-error-text">{errors.email}</span>
              )}
            </div>

            <div className="login-field">
              <label htmlFor="password" className="login-label">
                Contraseña
              </label>
              <input
                id="password"
                type="password"
                autoComplete="current-password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className={`login-input ${
                  errors.password ? "login-input--error" : ""
                }`}
                placeholder="••••••••"
              />
              {errors.password && (
                <span className="login-error-text">{errors.password}</span>
              )}
            </div>

            <div className="login-meta">
              <span className="login-meta-text">
                Solo se permiten correos del dominio{" "}
                <strong>@inf.udec.cl</strong>.
              </span>
            </div>

            <button
              type="submit"
              className="login-submit-btn"
              disabled={isSubmitting}
            >
              {isSubmitting ? "Validando credenciales..." : "Iniciar sesión"}
            </button>
          </form>

          <footer className="login-footer">
            <p className="login-footer-text">
              ¿Problemas para acceder? Contacta al docente o al administrador
              del laboratorio.
            </p>
          </footer>
        </section>
      </div>
    </div>
  );
};

export default Login;
