// src/screens/RenderForm.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import getTask, {
  numericalInputOptions,
  serverURL,
  baseURL,
  tasks,
} from "../common/Constants.js";
import "./RenderForm.css";

const defaultParams = {
  lcs: { inputSize: 500, samples: 30 },
  camm: { inputSize: 5000, samples: 30 },
  size: { inputSize: 2500, samples: 30 },
};

const inputSizePresets = {
  lcs: [500, 750, 1000],
  camm: [2000, 5000, 10000],
  size: [1000, 2500, 5000],
};

const samplesPresets = [10, 20, 30];

const machineOptions = [
  {
    id: "medidora",
    name: "Máquina medidora principal",
    description: "CPU Intel i5-9400 · 23GB RAM · Linux Mint 22.",
  },
  {
    id: "local",
    name: "Ejecución local (mock)",
    description: "Solo para pruebas de interfaz. No registra métricas reales.",
    disabled: true,
  },
];

const executionProfiles = [
  {
    id: "rapido",
    name: "Rápido",
    description: "Menos repeticiones, ideal para pruebas preliminares.",
  },
  {
    id: "equilibrado",
    name: "Equilibrado",
    description: "Buen balance entre tiempo y precisión de las métricas.",
  },
  {
    id: "exhaustivo",
    name: "Exhaustivo",
    description: "Más repeticiones para obtener mediciones más estables.",
  },
];

function RenderForm() {
  const [file, setFile] = useState(null);
  const [testName, setTestName] = useState("");
  const [inputSize, setInputSize] = useState(1000);
  const [samples, setSamples] = useState(30);
  const [selectedTaskType, setSelectedTaskType] = useState("");
  const [dataType, setDataType] = useState("");
  const [selectedMachine, setSelectedMachine] = useState("medidora");
  const [executionProfile, setExecutionProfile] = useState("equilibrado");

  const [fileList, setFileList] = useState([]);
  const [messages, setMessages] = useState([]);
  const [check, setCheck] = useState(true); // habilita botón "Ver estadísticas"
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOverview, setShowOverview] = useState(false);

  const navigate = useNavigate();

  // 🔁 Polling de estado para cada archivo en fileList
  useEffect(() => {
    if (!fileList || fileList.length === 0) return;

    const interval = setInterval(() => {
      const requests = fileList.map((code) =>
        axios
          .get(`${serverURL}status/${code}_status.json`, {
            headers: { "Cache-Control": "no-cache" },
          })
          .then((res) => ({
            codename: code,
            originalName:
              res.data.files && res.data.files.length > 0
                ? res.data.files[0].original_filename
                : code,
            messages: res.data.messages || [],
          }))
          .catch(() => null)
      );

      Promise.all(requests).then((results) => {
        let allMessages = [];
        let allDone = true;

        results.forEach((res) => {
          if (res && Array.isArray(res.messages)) {
            allMessages.push({
              codename: res.codename,
              originalName: res.originalName,
              messages: res.messages,
            });

            const isDone = res.messages.some((m) =>
              m.msg.includes("✅ Resultados listos.")
            );
            if (!isDone) allDone = false;
          }
        });

        if (allMessages.length > 0) {
          setMessages(allMessages);
        }

        if (allDone && allMessages.length > 0) {
          setCheck(false);
          setIsSubmitting(false);
          clearInterval(interval);
        }
      });
    }, 3000);

    return () => clearInterval(interval);
  }, [fileList]);

  // ======================= HANDLERS =======================

  const handleTaskChange = (taskId) => {
    if (selectedTaskType !== taskId) {
      setDataType("");
    }

    setSelectedTaskType(taskId);

    const params = defaultParams[taskId];
    if (params) {
      setInputSize(params.inputSize);
      setSamples(params.samples);
    }
  };

  const handleDataTypeChange = (type) => {
    setDataType(type);
  };

  const handleFileChange = (event) => {
    const uploadedFile = event.target.files[0];
    if (uploadedFile && uploadedFile.name.endsWith(".zip")) {
      setFile(uploadedFile);
    } else {
      alert("Por favor, sube un archivo .zip válido.");
      event.target.value = "";
    }
  };

  // En vez de ejecutar directamente, abrimos modal de overview
  const handleOpenOverview = (event) => {
    event.preventDefault();

    if (!file) {
      alert("Por favor, sube un archivo .zip.");
      return;
    }
    if (!selectedTaskType) {
      alert("Selecciona un tipo de test antes de ejecutar.");
      return;
    }

    setShowOverview(true);
  };

  // Lógica de envío real (antes en handleSubmit)
  const handleConfirmExecution = () => {
    if (!file || !selectedTaskType) return;

    const bodyFormData = new FormData();
    bodyFormData.append("file", file, file.name);
    bodyFormData.append("input_size", inputSize);
    bodyFormData.append("samples", samples);

    if (selectedTaskType) {
      bodyFormData.append("task_type", getTask(selectedTaskType));
    }
    if (dataType) {
      bodyFormData.append("data_type", dataType);
    }
    if (testName) {
      bodyFormData.append("test_name", testName);
    }
    bodyFormData.append("machine_profile", selectedMachine);
    bodyFormData.append("execution_profile", executionProfile);
    bodyFormData.append("username", "admin@inf.udec.cl (mock)");

    setIsSubmitting(true);
    setCheck(true);
    setMessages([]);
    setFileList([]);
    setShowOverview(false);

    axios({
      method: "post",
      url: baseURL,
      data: bodyFormData,
      headers: { "Content-Type": "multipart/form-data" },
    })
      .then((response) => {
        const queuedFiles = response.data.cpp_files_queued;
        if (queuedFiles && queuedFiles.length > 0 && queuedFiles[0].length > 0) {
          setMessages([]);
          setFileList(queuedFiles);
        } else {
          console.error("No se encontraron archivos en la respuesta");
          setIsSubmitting(false);
        }
      })
      .catch((error) => {
        console.error("❌ Error al enviar archivo:", error);
        setIsSubmitting(false);
      });
  };

  const handleCancelOverview = () => {
    setShowOverview(false);
  };

  const handleGoToResults = () => {
    if (!fileList || fileList.length === 0) return;

    const lastCode = fileList[fileList.length - 1];
    navigate("/code/" + lastCode, {
      replace: false,
      state: { name: testName || lastCode, codeList: fileList },
    });
  };

  // Estado global para el chip de estado en el panel derecho
  const getGlobalStatusChip = () => {
    if (messages.length === 0) {
      if (isSubmitting) {
        return {
          label: "Ejecutando…",
          className: "status-chip status-chip-running",
        };
      }
      return null;
    }

    const hasError = messages.some((group) =>
      group.messages.some(
        (m) =>
          m.msg.toLowerCase().includes("error") || m.msg.includes("❌")
      )
    );

    if (hasError) {
      return {
        label: "Error detectado",
        className: "status-chip status-chip-error",
      };
    }

    if (!check) {
      return {
        label: "Resultados listos",
        className: "status-chip status-chip-done",
      };
    }

    return {
      label: "Ejecutando…",
      className: "status-chip status-chip-running",
    };
  };

  const statusChip = getGlobalStatusChip();

  // Utilitarios para mostrar texto en el modal
  const getTaskTitle = () => {
    const t = tasks.find((task) => task.id === selectedTaskType);
    return t ? t.title : "-";
  };

  const getMachineLabel = () => {
    const m = machineOptions.find((opt) => opt.id === selectedMachine);
    return m ? m.name : "-";
  };

  const getExecutionProfileLabel = () => {
    const p = executionProfiles.find((opt) => opt.id === executionProfile);
    return p ? p.name : "-";
  };

  const getDataTypeLabel = () => {
    if (!dataType) return "No aplica";
    const opt = numericalInputOptions.find((o) => o.value === dataType);
    return opt ? opt.label : dataType;
  };

  return (
    <div className="inicio-container">
      {/* Header superior con usuario hardcodeado */}
      <div className="inicio-header">
        <div className="inicio-header-left">
          <h1 className="inicio-title">Configuración del test</h1>
          <p className="inicio-subtitle">
            Define el tipo de prueba, parámetros de entrada y entorno de medición antes de
            ejecutar el test de rendimiento.
          </p>
        </div>
        <div className="inicio-header-user">
          <span className="inicio-user-label">Usuario autenticado</span>
          <div className="inicio-user-pill">admin@inf.udec.cl (mock)</div>
        </div>
      </div>

      <form onSubmit={handleOpenOverview}>
        {/* Encabezado de paso dentro del cuerpo, no como card */}
        <div className="rf-step-header">
          <span className="rf-step-kicker">Paso 1</span>
        </div>

        <div
          className={`rf-main-layout ${
            fileList.length === 0 ? "no-status-panel" : ""
          }`}
        >
          {/* =================== COLUMNA IZQUIERDA: CONFIGURACIÓN =================== */}
          <div className="rf-main-left">
            {/* Bloque: Nombre y archivo */}
            <div className="rf-row rf-row-two">
              <section className="rf-panel">
                <label className="form-label">
                  <span className="label-icon">🏷️</span>
                  Nombre del test
                </label>
                <input
                  type="text"
                  value={testName}
                  onChange={(e) => setTestName(e.target.value)}
                  className="form-input"
                  placeholder="Ej: LCS optimizado, CAMM bloqueado, etc."
                />
                <p className="form-help-text">
                  Este nombre se usará para identificar la ejecución en la vista de
                  resultados.
                </p>
              </section>

              <section className="rf-panel">
                <label className="form-label">
                  <span className="label-icon">📁</span>
                  Archivo de código (.zip)
                </label>
                <div className="file-upload">
                  <label className="file-upload-button">
                    <span className="file-upload-main-text">Seleccionar archivo</span>
                    <input
                      type="file"
                      accept=".zip"
                      onChange={handleFileChange}
                      className="file-input-hidden"
                    />
                  </label>
                  <span className="file-upload-label">
                    {file ? file.name : "Sin archivos seleccionados"}
                  </span>
                </div>
                <p className="form-help-text">
                  El archivo <code>.zip</code> debe contener uno o más archivos{" "}
                  <code>.cpp</code> compilables.
                </p>
              </section>
            </div>

            {/* Bloque: Tipo de test + parámetros */}
            <div className="rf-row">
              <section className="rf-panel">
                <label className="form-label">
                  <span className="label-icon">🧪</span>
                  Tipo de test y parámetros
                </label>

                <div className="test-options">
                  {tasks.map((task) => (
                    <div
                      key={task.id}
                      className={`test-option ${
                        selectedTaskType === task.id ? "selected" : ""
                      }`}
                      onClick={() => handleTaskChange(task.id)}
                    >
                      <label className="test-radio-label">
                        <input
                          type="radio"
                          className="test-radio"
                          name="taskToggle"
                          checked={selectedTaskType === task.id}
                          onChange={() => handleTaskChange(task.id)}
                        />
                        <span className="test-title">{task.title}</span>
                      </label>

                      {selectedTaskType === task.id && (
                        <div className="test-details">
                          <p className="test-description">
                            {task.description}
                          </p>

                          <div className="test-params-grid">
                            <div className="param-group">
                              <label className="param-label">
                                Tamaño máximo de entrada
                              </label>
                              <input
                                type="number"
                                className="param-input"
                                value={inputSize}
                                onChange={(e) =>
                                  setInputSize(Number(e.target.value) || 0)
                                }
                                min="1"
                              />
                              <div className="param-suggestions">
                                {(inputSizePresets[task.id] || []).map(
                                  (preset) => (
                                    <button
                                      key={preset}
                                      type="button"
                                      className="param-chip"
                                      onClick={() => setInputSize(preset)}
                                    >
                                      {preset}
                                    </button>
                                  )
                                )}
                              </div>
                            </div>

                            <div className="param-group">
                              <label className="param-label">
                                Repeticiones por incremento
                              </label>
                              <input
                                type="number"
                                className="param-input"
                                value={samples}
                                onChange={(e) =>
                                  setSamples(Number(e.target.value) || 0)
                                }
                                min="1"
                              />
                              <div className="param-suggestions">
                                {samplesPresets.map((preset) => (
                                  <button
                                    key={preset}
                                    type="button"
                                    className="param-chip"
                                    onClick={() => setSamples(preset)}
                                  >
                                    {preset}
                                  </button>
                                ))}
                              </div>
                            </div>

                            {selectedTaskType === "camm" && (
                              <div className="param-group param-group-full">
                                <label className="param-label">
                                  Tipo de datos (CAMM)
                                </label>
                                <div className="data-options">
                                  {numericalInputOptions.map((option) => (
                                    <label
                                      key={option.value}
                                      className="data-option"
                                    >
                                      <input
                                        type="radio"
                                        name="dataType"
                                        value={option.value}
                                        onChange={(e) =>
                                          handleDataTypeChange(e.target.value)
                                        }
                                        checked={dataType === option.value}
                                        className="data-radio"
                                      />
                                      <span className="data-label">
                                        {option.label}
                                      </span>
                                    </label>
                                  ))}
                                </div>
                              </div>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </section>
            </div>

            {/* Bloque: Sistema de medición + perfil de ejecución */}
            <div className="rf-row rf-row-two">
              <section className="rf-panel">
                <label className="form-label">
                  <span className="label-icon">🖥️</span>
                  Sistema de medición
                </label>
                <div className="machine-options">
                  {machineOptions.map((m) => (
                    <button
                      type="button"
                      key={m.id}
                      className={`machine-option ${
                        selectedMachine === m.id ? "selected" : ""
                      }`}
                      onClick={() => !m.disabled && setSelectedMachine(m.id)}
                      disabled={m.disabled}
                    >
                      <div className="machine-option-header">
                        <span className="machine-name">{m.name}</span>
                      </div>
                      <p className="machine-description">
                        {m.description}
                        {m.disabled && " (no disponible en esta versión)"}
                      </p>
                    </button>
                  ))}
                </div>
              </section>

              <section className="rf-panel">
                <label className="form-label">
                  <span className="label-icon">⚙️</span>
                  Perfil de ejecución
                </label>
                <div className="execution-options">
                  {executionProfiles.map((profile) => (
                    <label
                      key={profile.id}
                      className={`execution-option ${
                        executionProfile === profile.id ? "selected" : ""
                      }`}
                    >
                      <input
                        type="radio"
                        name="executionProfile"
                        value={profile.id}
                        checked={executionProfile === profile.id}
                        onChange={(e) => setExecutionProfile(e.target.value)}
                      />
                      <div className="execution-body">
                        <span className="execution-name">
                          {profile.name}
                        </span>
                        <span className="execution-description">
                          {profile.description}
                        </span>
                      </div>
                    </label>
                  ))}
                </div>
              </section>
            </div>
          </div>

          {/* =================== PANEL DERECHO: ESTADO DEL CÓDIGO =================== */}
          {fileList.length > 0 && (
            <aside className="rf-main-right">
              <div className="rf-status-panel">
                <div className="rf-status-header">
                  <span className="rf-status-kicker">Paso 2</span>
                  <h3 className="rf-status-title">Estado del código</h3>
                  <p className="rf-status-subtitle">
                    Seguimiento de compilación, ejecución y generación de resultados.
                  </p>
                </div>

                <div className="status-content">
                  <div className="status-summary">
                    {statusChip && (
                      <span className={statusChip.className}>
                        {statusChip.label}
                      </span>
                    )}
                    <p className="status-summary-text">
                      Archivos en esta ejecución:{" "}
                      <strong>{fileList.length}</strong>
                    </p>
                  </div>

                  <div className="status-box">
                    {messages.length === 0 ? (
                      <div className="status-empty">
                        <span className="status-icon">⏳</span>
                        <p>Se está ejecutando el test y recopilando métricas…</p>
                      </div>
                    ) : (
                      <div className="status-messages">
                        {messages.map((group, idx) => (
                          <div key={idx} className="status-group">
                            <h4 className="codename-title">
                              Archivo:{" "}
                              <span style={{ fontWeight: 600 }}>
                                {group.originalName}
                              </span>
                            </h4>
                            {group.messages.map((entry, index) => (
                              <div key={index} className="status-message">
                                <span className="message-time">
                                  [{entry.time}]
                                </span>
                                <span className="message-text">
                                  {entry.msg}
                                </span>
                              </div>
                            ))}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>

                  <button
                    type="button"
                    className={`results-button ${check ? "disabled" : ""}`}
                    onClick={handleGoToResults}
                    disabled={check}
                  >
                    Ver estadísticas
                  </button>
                </div>
              </div>
            </aside>
          )}
        </div>

        {/* Barra inferior de acciones */}
        <div className="rf-footer-bar">
          <button
            type="submit"
            className={`submit-button ${
              !selectedTaskType || !file || isSubmitting ? "disabled" : ""
            }`}
            disabled={!selectedTaskType || !file || isSubmitting}
          >
            {isSubmitting ? "Ejecutando test..." : "Revisar y ejecutar"}
          </button>
          <p className="run-hint">
            Se mostrará un resumen con los parámetros seleccionados antes de ejecutar el
            test en la máquina medidora.
          </p>
        </div>
      </form>

      {/* =================== MODAL DE OVERVIEW =================== */}
      {showOverview && (
        <div className="rf-modal-backdrop">
          <div className="rf-modal">
            <div className="rf-modal-header">
              <h3>Resumen del test</h3>
              <p>
                Revisa los datos principales antes de enviar el código a la máquina
                medidora.
              </p>
            </div>

            <div className="rf-modal-body">
              <div className="rf-modal-grid">
                <div className="rf-modal-section">
                  <h4>Información general</h4>
                  <dl>
                    <dt>Nombre del test</dt>
                    <dd>{testName || "(sin nombre)"}</dd>

                    <dt>Archivo</dt>
                    <dd>{file ? file.name : "Ningún archivo seleccionado"}</dd>

                    <dt>Tipo de test</dt>
                    <dd>{getTaskTitle()}</dd>
                  </dl>
                </div>

                <div className="rf-modal-section">
                  <h4>Parámetros</h4>
                  <dl>
                    <dt>Tamaño máximo de entrada</dt>
                    <dd>{inputSize}</dd>

                    <dt>Repeticiones por incremento</dt>
                    <dd>{samples}</dd>

                    <dt>Tipo de datos (CAMM)</dt>
                    <dd>{getDataTypeLabel()}</dd>
                  </dl>
                </div>

                <div className="rf-modal-section">
                  <h4>Entorno de medición</h4>
                  <dl>
                    <dt>Máquina</dt>
                    <dd>{getMachineLabel()}</dd>

                    <dt>Perfil de ejecución</dt>
                    <dd>{getExecutionProfileLabel()}</dd>

                    <dt>Usuario</dt>
                    <dd>admin@inf.udec.cl (mock)</dd>
                  </dl>
                </div>
              </div>
            </div>

            <div className="rf-modal-footer">
              <button
                type="button"
                className="rf-modal-secondary"
                onClick={handleCancelOverview}
              >
                Volver y editar
              </button>
              <button
                type="button"
                className="rf-modal-primary"
                onClick={handleConfirmExecution}
                disabled={isSubmitting}
              >
                {isSubmitting ? "Ejecutando…" : "Confirmar y ejecutar"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default RenderForm;
